class GlyphEngine final : public QIconEngine {
public:
    explicit GlyphEngine(const QString& glyph) : m_glyph(glyph) {}
    QIconEngine* clone() const override { return new GlyphEngine(m_glyph); }
    QPixmap pixmap(const QSize& size, QIcon::Mode mode, QIcon::State) override {
        QPixmap pm(size);
        pm.fill(Qt::transparent);
        fluent::FontIcon renderer(m_glyph);
        renderer.setIconSize(qMin(size.width(), size.height()));
        renderer.setEnabled(mode != QIcon::Disabled);
        renderer.resize(size);
        QPainter painter(&pm);
        renderer.render(&painter, QPoint(), QRegion(), QWidget::DrawChildren);
        return pm;
    }
    void paint(QPainter* painter, const QRect& rect, QIcon::Mode mode, QIcon::State state) override {
        const int dpr = painter->device() ? qMax(1, qRound(painter->device()->devicePixelRatioF())) : 1;
        painter->drawPixmap(rect, pixmap(rect.size() * dpr, mode, state));
    }
private:
    QString m_glyph;
};
auto* anchor = new fluent::basicinput::Button(QStringLiteral("Selection"), %PARENT%);
anchor->move(148, 16);
anchor->show();
auto* control = new fluent::menus_toolbars::CommandBarFlyout(%PARENT%);
control->setAnimationEnabled(false);
control->setAnchor(anchor);
control->setLightDismissConsumesPress(true);
auto makeCommand = [&](const QString& text, const QString& glyph, QKeySequence::StandardKey shortcut) {
    auto* action = new QAction(text, control);
    action->setIcon(QIcon(new GlyphEngine(glyph)));
    if (shortcut != QKeySequence::UnknownKey)
        action->setShortcut(shortcut);
    return action;
};
control->addPrimaryAction(makeCommand(QStringLiteral("Cut"), Typography::Icons::Cut, QKeySequence::Cut));
control->addPrimaryAction(makeCommand(QStringLiteral("Copy"), Typography::Icons::Copy, QKeySequence::Copy));
control->addPrimaryAction(makeCommand(QStringLiteral("Delete"), Typography::Icons::Delete, QKeySequence::Delete));
control->addSecondaryAction(makeCommand(QStringLiteral("Share"), Typography::Icons::Share, QKeySequence::UnknownKey));
control->addSecondaryAction(makeCommand(QStringLiteral("Select all"), Typography::Icons::SelectAll, QKeySequence::SelectAll));
auto* favorite = makeCommand(QStringLiteral("Favorite"), Typography::Icons::FavoriteStar, QKeySequence::UnknownKey);
favorite->setCheckable(true);
control->addSecondaryAction(favorite);
QObject::connect(anchor, &fluent::basicinput::Button::clicked, control, &fluent::menus_toolbars::CommandBarFlyout::open);
